'use strict';
const ENDING_CLIPS={
 schuldig:{title:'Schuldig',subtitle:'Urteilsfassung: Verurteilung',src:'media/urteile/schuldig.mp4',duration:'5:02',pages:87},
 unschuldig:{title:'Unschuldig',subtitle:'Urteilsfassung: Freispruch',src:'media/urteile/unschuldig.mp4',duration:'5:25',pages:91}
};
const ENDING_QUESTIONS=[
 {id:'wahl',phase:'before',title:'Warum möchtest du gerade dieses Ende zuerst sehen?',prompt:'Suchst du Bestätigung deiner Meinung, willst du die Gegenposition verstehen oder bist du noch unentschieden? Unterscheide den Grund für deinen Klick von deinem Urteil über Koch.',answer:'Ein Klick kann Zustimmung ausdrücken, aber auch Neugier auf die Gegenposition. Beispiel: Ich neige zum Freispruch, sehe aber zuerst die Verurteilung, um meinen stärksten Einwand zu prüfen. Nenne deinen tatsächlichen Beweggrund. Ein Bestätigungsfehler entsteht, wenn wir bevorzugt Informationen wählen und ernst nehmen, die unsere vorhandene Meinung stützen. Ich unterscheide daher meine Auswahl von meinem Urteil. Meine offene Frage lautet: Welches Argument könnte meine Meinung verändern?',criteria:[['Grund der Wahl','self','Beschreibe in der Ich-Form, was du mit deiner Auswahl herausfinden willst.',84],['Klick und Urteil unterscheiden','distinguish','Der zuerst gewählte Clip muss nicht deiner Meinung entsprechen.',84],['Gegenposition ernst nehmen','question','Formuliere eine offene Frage an die Gegenposition.',85]],refs:[[84,'Letztes Wort und Übergang zur Beratung'],[85,'Aufforderung zum eigenen Urteil']]},
 {id:'vorurteil',phase:'before',title:'Welches Urteil hältst du vor der Sichtung für überzeugend – und warum?',prompt:'Formuliere dein vorläufiges Urteil oder deine begründete Unsicherheit. Nenne einen Textbefund und den Massstab, nach dem du entscheidest. Was müsste sich zeigen, damit du deine Meinung änderst?',answer:'Eine begründete Position verbindet einen Befund mit einem Massstab: Die Tatsache ist, dass Koch die Passagiere bewusst tötet; für meine Bewertung ist etwa ihre gleiche Würde oder die Rettung möglichst vieler Menschen entscheidend. Ich muss erklären, weshalb der gewählte Massstab hier gelten soll. Auch ein offenes Urteil ist möglich, wenn ich genau benenne, welche Unsicherheit mich daran hindert. Nenne ausserdem einen denkbaren Einwand, der deine Position verändern könnte.',criteria:[['Befund aus dem Fall','fact','Nenne eine konkrete Handlung oder Tatsache aus dem Fall.',12],['Massstab','norm','Erkläre deine Regel oder deinen Massstab; eine Gefühlsäusserung allein genügt noch nicht.',79],['Revisionsbereitschaft','uncertain','Nenne eine offene Frage oder eine mögliche Information, die dein Urteil verändern könnte.',80]],refs:[[12,'Tatvorwurf'],[79,'Würde als Massstab'],[80,'Offene Rettungsmöglichkeiten']]},
 {id:'argument',phase:'after',title:'Wie wird das gewählte Urteil begründet?',prompt:'Rekonstruiere das stärkste Argument in drei Schritten: Welche Tatsache wird angenommen? Welche Regel verbindet sie mit der Bewertung? Welcher Schluss wird daraus gezogen? Notiere eine Zeitmarke aus dem Clip.',answer:'Im Freispruch lässt sich rekonstruieren: Koch handelt aus Rettungsabsicht; selbstloses Handeln in dieser extremen Lage soll entschuldigt werden; daraus folgt in dieser Fassung der Freispruch. Im Schuldspruch steht die Tötung Unbeteiligter im Zentrum; deren Würde soll auch in einer Notlage nicht verrechnet werden; daraus folgt die Verurteilung. Dies sind zunächst die Argumente der Fassungen. Prüfe ihre Voraussetzungen und belege deine Rekonstruktion mit einer konkreten Aussage und Zeitmarke. Der Schluss muss aus der genannten Regel und dem belegten Befund nachvollziehbar folgen.',criteria:[['Voraussetzung','premise','Formuliere die angenommene Voraussetzung, etwa mit «weil» oder «wenn».',92],['Regel','norm','Nenne die normative Verbindung zwischen Tatsache und Urteil.',90],['Schluss mit Beleg','conclusion+evidence','Formuliere den Schluss und belege ihn durch eine Aussage oder Textstelle.',92]],refs:[[90,'Begründung des Schuldspruchs'],[92,'Begründung des Freispruchs']]},
 {id:'gegenargument',phase:'after',title:'Was ist das stärkste Argument gegen dein bevorzugtes Urteil?',prompt:'Stelle die Gegenposition so fair dar, dass ihre Vertreterinnen und Vertreter sich darin wiedererkennen würden. Antworte darauf. Welcher Einwand bleibt trotzdem bestehen?',answer:'Wer zum Freispruch neigt, sollte den Einwand prüfen, dass der Staat unbeteiligte Personen nicht zur Rettung anderer verfügbar machen darf. Wer zur Verurteilung neigt, sollte Kochs selbstlose Rettungsabsicht und seine extreme Entscheidungslage ernst nehmen. Eine faire Antwort nennt zunächst das starke Gegenargument und legt dann dar, warum der eigene Massstab dennoch trägt. Der verbleibende Widerspruch darf benannt werden; er muss nicht durch eine Abwertung der anderen Seite verschwinden.',criteria:[['Gegenposition rekonstruieren','interpret','Erläutere, wie die andere Seite den Fall deutet.',90],['Begründet antworten','norm','Begründe deine Antwort anhand einer Regel oder eines Massstabs.',92],['Bleibende Schwierigkeit','open','Benenne einen offenen Widerspruch statt die Gegenposition lächerlich zu machen.',93]],refs:[[90,'Rechtsgrenzen im Schuldspruch'],[92,'Rettungsabsicht im Freispruch'],[93,'Grenzen der rechtlichen Lösung']]},
 {id:'wissen',phase:'after',title:'Wo wird eine unsichere Annahme wie eine sichere Tatsache behandelt?',prompt:'Untersuche die mögliche Selbstrettung der Passagiere oder ein Hochziehen der Maschine. Was wusste Koch damals? Was weiss das Gericht später? Warum beweist fehlender Nachweis einer Rettung noch nicht deren Unmöglichkeit?',answer:'Koch sagt, er habe die Selbstrettungsversuche nicht beobachtet. Der Vorsitzende verweist später auf die Blackbox; Meisers SMS berichtet ebenfalls von einem Versuch. Diese Informationen beweisen weder eine sichere Rettung noch ein sicheres Scheitern. Im Freispruch werden die Rettungsmöglichkeiten als unbewiesen zurückgewiesen. Prüfe, wie die Begründung Unsicherheit gewichtet. Späteres Prozesswissen und Kochs damalige Kenntnis sind zu unterscheiden.',criteria:[['Damals und später unterscheiden','knowledge+distinguish','Trenne Kochs damaligen Wissensstand vom späteren Prozesswissen.',51],['Versuch als Beleg','attempt+evidence','Erkläre, was die Informationen tatsächlich belegen: einen Versuch.',68],['Grenze der Gewissheit','uncertain','Weder Erfolg noch Scheitern sind damit sicher bewiesen.',92]],refs:[[51,'Kochs Wahrnehmung und Blackbox'],[68,'SMS'],[71,'Offener Ausgang des Versuchs'],[92,'Umgang mit Rettungsmöglichkeiten']]},
 {id:'motiv',phase:'after',title:'Macht ein selbstloses Motiv die Tötung schon rechtmässig?',prompt:'Unterscheide Motiv, Rechtfertigung und Entschuldigung. Motiv fragt: Warum handelt jemand? Rechtfertigung fragt: Ist die Handlung erlaubt? Entschuldigung fragt: Ist dem Handelnden die rechtswidrige Tat persönlich vorwerfbar? Auf welcher Ebene argumentiert der Freispruch?',answer:'Koch will Menschen retten: Das Motiv bezeichnet seine Rettungsabsicht. Eine Rechtfertigung würde die Handlung als erlaubt bewerten; eine Entschuldigung betrifft die persönliche Vorwerfbarkeit trotz rechtswidriger Handlung. Die Freispruchsfassung argumentiert mit einem übergesetzlichen Entschuldigungsgrund und Kochs Selbstlosigkeit. Aus einem guten Motiv folgt daher nicht automatisch eine allgemeine Erlaubnis zum Abschuss. Die literarische Fassung entscheidet einen Einzelfall innerhalb der Versuchsanordnung.',criteria:[['Motiv','value','Nenne Kochs Rettungsabsicht als Motiv.',92],['Ebenen unterscheiden','distinguish+permission','Erkläre den Unterschied zwischen erlaubter Handlung und persönlicher Entschuldigung.',92],['Einzelfall statt Freigabe','criminal','Beziehe die Argumentation auf Kochs persönliche Strafbarkeit im Einzelfall.',92]],refs:[[82,'Verfassungsfrage und persönliche Strafbarkeit'],[92,'Übergesetzliche Entschuldigung']]},
 {id:'zahlen',phase:'after',title:'Was leistet das Zahlenargument – und was lässt es offen?',prompt:'Die Rechnung stellt 164 Menschen im Flugzeug 70’000 bedrohten Menschen gegenüber. Welche zusätzliche Annahme braucht der Schluss «Also musste Koch schiessen»? Prüfe Gewissheit, Alternativen und die Erlaubnis, andere zu opfern.',answer:'Die Zahlen zeigen die Grössenordnung der bedrohten Gruppen. Der Schluss auf eine Pflicht zum Abschuss benötigt jedoch zusätzliche Voraussetzungen: Der erwartete Verlauf muss hinreichend sicher sein, andere Möglichkeiten müssten ausscheiden, und die Tötung Unbeteiligter müsste nach einem begründeten Massstab zulässig sein. Die Zahl allein liefert diese Regel nicht. Nelson bestreitet gerade die Verrechnung gleicher Menschenwürde; die Verteidigung betont das kleinere Übel.',criteria:[['Zusätzliche Voraussetzung','premise','Benenne die Annahme zwischen Zahlenvergleich und Handlungsschluss.',79],['Alternativen und Unsicherheit','uncertain','Prüfe, ob Verlauf und Alternativlosigkeit tatsächlich feststehen.',80],['Normative Grenze','dignity+norm','Prüfe, ob und warum eine Abwägung die Tötung erlauben soll.',79]],refs:[[36,'Evakuierung als Alternative'],[79,'Verrechnung und Würde'],[80,'Ungewisse Rettungswege'],[92,'Kleineres Übel']]},
 {id:'inszenierung',phase:'after',title:'Wodurch lässt der Film das Urteil überzeugend oder verstörend erscheinen?',prompt:'Beschreibe eine konkrete Einstellung mit Zeitmarke: Blick, Stimme, Pause, Kameranähe, Reaktionsschnitt oder Musik. Trenne die beobachtbare Gestaltung von ihrer vermuteten Wirkung. Würde dasselbe Argument ohne dieses Bild ebenso wirken?',answer:'Eine mögliche Untersuchung verbindet eine genaue Beobachtung mit einer vorsichtigen Deutung: Eine Pause, ein Reaktionsbild oder die Stimme des Richters kann Nähe, Distanz oder Zweifel erzeugen. Die Wirkung ist nicht für alle Zuschauenden gleich. Belege daher die gewählte Stelle im Clip mit einer Zeitmarke. Ich unterscheide meine Deutung vom Beleg. Ein emotional starkes Bild ist noch kein zusätzlicher Beweis für die Richtigkeit des juristischen Schlusses. Vergleiche dazu, welche Spielanweisungen der Buchtext tatsächlich vorgibt.',criteria:[['Beobachtung','perception','Nenne, was du an einer konkreten Stelle gesehen oder gehört hast.',90],['Wirkungshypothese','effect','Erkläre eine mögliche Wirkung, ohne sie allen Zuschauenden zu unterstellen.',93],['Beleg und Deutung trennen','evidence+distinguish','Notiere einen Beleg beziehungsweise eine Zeitmarke und unterscheide Gestaltung von Schlussfolgerung.',90]],refs:[[90,'Szenischer Schluss des Schuldspruchs'],[93,'Szenischer Schluss des Freispruchs']]},
 {id:'vergleich',phase:'compare',title:'Beide Enden gesehen: Was bleibt gleich und was wird anders gewichtet?',prompt:'Vergleiche dieselbe Tatsache in beiden Begründungen, etwa Kochs Gewissensbemühen. Welche Bedeutung erhält sie jeweils? Welche Folge hätte es, den gewählten Massstab künftig auch auf andere Fälle anzuwenden?',answer:'Beide Fassungen erkennen Kochs ernsthaftes Gewissensbemühen an; dies ist durch Aussagen in beiden Urteilsbegründungen belegt. Im Freispruch trägt die besondere selbstlose Entscheidungslage zur Entschuldigung bei; im Schuldspruch hebt sie die Grenze zum Schutz der Passagiere nicht auf. Der Unterschied liegt damit auch in der Gewichtung eines gemeinsamen Befunds. Frage anschliessend, ob der jeweilige Massstab verallgemeinerbar wäre und welche Personen er in künftigen Situationen schützt oder gefährdet.',criteria:[['Gemeinsamer Befund','shared+evidence','Nenne einen in beiden Fassungen vorkommenden Befund.',90],['Andere Gewichtung','weigh','Erkläre den Unterschied seiner Bedeutung für das Urteil.',92],['Verallgemeinerung','universal','Prüfe die Konsequenz des Massstabs über diesen Einzelfall hinaus.',90]],refs:[[90,'Gewissensbemühen und Vorbildgefahr'],[92,'Gewissensbemühen und Entschuldigung']]},
 {id:'revision',phase:'compare',title:'Wie lautet dein Urteil jetzt – und was hat sich an deiner Begründung verändert?',prompt:'Vergleiche mit deiner Notiz vor der Sichtung. Nenne einen konkreten Grund für Beibehaltung, Änderung oder Offenhalten deines Urteils. Halte einen gewichtigen Einwand gegen die eigene Position fest. Ein Meinungswechsel ist keine Pflicht.',answer:'Die Reflexion kann beim ursprünglichen Urteil bleiben, es verändern oder bewusst offenhalten. Entscheidend ist ein nachvollziehbarer Grund: Welcher Beleg oder welches Argument wurde neu gewichtet? Formuliere deinen jetzigen Massstab und einen ernsthaften Einwand gegen ihn. Ein Lernfortschritt liegt auch darin, bei gleichem Ergebnis präziser und weniger vorschnell zu argumentieren. Weder Mehrheitszustimmung noch Sympathie für eine Figur ersetzt die Begründung.',criteria:[['Textgestützter Grund','evidence','Nenne einen konkreten Beleg, der für dein jetziges Urteil wichtig ist.',85],['Eigener Massstab','norm','Erkläre, nach welchem Massstab du jetzt entscheidest.',90],['Offener Einwand','open','Benenne eine bleibende Frage oder Schwierigkeit deiner eigenen Position.',93]],refs:[[85,'Eigenes Urteil und Begründung'],[90,'Schutzgrenzen'],[93,'Bleibende Konflikte']]}
];
for(const q of ENDING_QUESTIONS)TERROR_FEEDBACK.rubrics['filmende-'+q.id]={criteria:q.criteria.map(([label,groups,reason,page])=>({label,groups:groups.split('+'),reason,page})),answer:q.answer,refs:q.refs,creative:true};
function endingEntry(){return `<section class="section card ending-entry"><span class="eyebrow">ZUM ABSCHLUSS DER FILMVISIONIERUNG</span><h2>Schuldig oder unschuldig? Wähle dein erstes Ende.</h2><p>Halte deine Meinung fest, wähle eine Urteilsfassung und prüfe danach die Gegenposition. Zwei getrennte Schlussclips, Reflexionsfragen und Musterantworten helfen dir beim begründeten Vergleich.</p><a class="button" href="#film/abschluss">Beide Filmenden & Reflexion öffnen →</a></section>`;}
function endingFeedbackHTML(id,text){return readerFeedbackHTML(id,text).replace(/<button type="button" class="feedback-reference" data-feedback-page="(\d+)" title="[^"]*">([\s\S]*?)<\/button>/g,(_,page,label)=>`<a class="feedback-reference" href="media/text/Schirach_Terror_9783641203290.pdf#page=${page}" target="_blank" rel="noopener">${label}</a>`).replace('«Antwort prüfen»','«Reflexion prüfen»');}
function endingQuestion(q){const key='filmende-'+q.id;return `<details class="ending-question" ${q.phase==='before'?'open':''}><summary>${escape(q.title)}</summary><div><p>${escape(q.prompt)}</p><div data-ending-question="${key}">${note(key,'Filmabschluss · '+q.title,'Begründe in eigenen Worten; notiere bei Beobachtungen auch eine Zeitmarke.')}<button class="secondary small" type="button" data-ending-check>Reflexion prüfen</button><div class="reader-feedback" data-ending-feedback aria-live="polite">${endingFeedbackHTML(key,state.notes[key]?.text||'')}</div></div></div></details>`;}
function endingPlayerHTML(key){const c=ENDING_CLIPS[key];return c?`<h3>${c.title} · ${c.subtitle}</h3><video id="endingPlayer" controls playsinline preload="metadata" poster="media/urteile/${key}.jpg" aria-label="Schlussclip ${c.title}"><source src="${c.src}" type="video/mp4"></video><p><a href="${c.src}">Clip direkt öffnen</a> · <a href="media/text/Schirach_Terror_9783641203290.pdf#page=${c.pages}" target="_blank" rel="noopener">Urteilsfassung im Buch: PDF S. ${c.pages} ↗</a></p><p data-ending-playback role="status">Bereit. Starte den Clip mit der Wiedergabetaste.</p>`:'<p class="ending-placeholder">Wähle oben, welches Ende du zuerst untersuchen möchtest. Es startet kein Film automatisch.</p>';}
function endingSelectionLabel(){const first=ENDING_CLIPS[state.prefs.endingFirstChoice],current=ENDING_CLIPS[state.prefs.endingChoice];return current?`Zuerst gewählt: ${first?.title||current.title}. Jetzt geöffnet: ${current.title}. Die Clipauswahl ist kein Abstimmungsvotum.`:'Noch kein Ende gewählt. Beide Fassungen bleiben jederzeit zugänglich.';}
function endingsWorkshop(){const selected=state.prefs.endingChoice;return `<section class="section ending-workshop" id="filmabschluss" aria-labelledby="endingTitle"><span class="eyebrow">FILMABSCHLUSS · ENTSCHEIDEN, ANSEHEN, HINTERFRAGEN</span><h2 id="endingTitle">Ein Fall. Zwei Urteile. Deine Gründe.</h2><p>Die beiden Schlussfassungen führen denselben Fall zu unterschiedlichen Urteilen. Entscheide zunächst, welches Ende du sehen möchtest. Schau danach auch das andere an. Deine Meinung darf sich verändern oder offenbleiben.</p><section class="card"><h3>1 · Vor der Auswahl: Was denkst du – und weshalb?</h3><p>Wenn du möchtest, notiere vorab deine Gründe. Beide Clips lassen sich auch ohne Eingabe direkt öffnen. Ein Klick auf «Unschuldig» bezeichnet hier die Filmfassung mit Freispruch; er bedeutet nicht, dass Koch den Abschuss nicht begangen hätte.</p>${ENDING_QUESTIONS.filter(q=>q.phase==='before').map(endingQuestion).join('')}</section><section class="card"><h3>2 · Wähle dein erstes Filmende</h3><div class="ending-choices">${Object.entries(ENDING_CLIPS).map(([key,c])=>`<article><h4>${c.title}</h4><p>${c.subtitle} · ${c.duration} Minuten</p><button type="button" data-ending-select="${key}" aria-pressed="${selected===key}">${c.title}: diesen Clip ansehen</button></article>`).join('')}</div><p id="endingSelection" role="status">${endingSelectionLabel()}</p><div id="endingPlayerMount">${endingPlayerHTML(selected)}</div><p class="notice">Du kannst jederzeit zum anderen Ende wechseln. Beim Wechsel wird die laufende Wiedergabe angehalten.</p></section><section class="card"><h3>3 · Nach dem ersten Ende: Argumente kritisch prüfen</h3><p>Prüfe Gründe und Voraussetzungen. Die Rückmeldung bewertet keine politische oder moralische Meinung als richtig oder falsch; sie hilft dir, deine Begründung auszubauen.</p>${ENDING_QUESTIONS.filter(q=>q.phase==='after').map(endingQuestion).join('')}</section><section class="card"><h3>4 · Gegenposition ansehen und Urteil überdenken</h3><p>Öffne oben die andere Fassung. Vergleiche anschliessend beide Begründungen; ein blosser Vergleich der Ergebnisse reicht nicht.</p>${ENDING_QUESTIONS.filter(q=>q.phase==='compare').map(endingQuestion).join('')}<p><a class="button" href="abstimmung/">Zur gemeinsamen Klassenabstimmung →</a> <a href="#journal">Reflexionen im Journal öffnen</a></p></section></section>`;}
const endingTimers=new WeakMap();
function updateEndingFeedback(box){if(box?.isConnected)box.querySelector('[data-ending-feedback]').innerHTML=endingFeedbackHTML(box.dataset.endingQuestion,box.querySelector('textarea').value);}
document.addEventListener('input',e=>{const box=e.target.closest('[data-ending-question]');if(!box||!e.target.matches('textarea'))return;clearTimeout(endingTimers.get(box));endingTimers.set(box,setTimeout(()=>updateEndingFeedback(box),650));});
document.addEventListener('click',e=>{const select=e.target.closest('[data-ending-select]');if(select){const key=select.dataset.endingSelect;if(!ENDING_CLIPS[key])return;document.querySelectorAll('video').forEach(v=>v.pause());if(!ENDING_CLIPS[state.prefs.endingFirstChoice])state.prefs.endingFirstChoice=key;state.prefs.endingChoice=key;save();document.getElementById('endingPlayerMount').innerHTML=endingPlayerHTML(key);document.getElementById('endingSelection').textContent=endingSelectionLabel();document.querySelectorAll('[data-ending-select]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.endingSelect===key)));document.getElementById('endingPlayerMount').scrollIntoView({block:'center',behavior:'smooth'});return;}const check=e.target.closest('[data-ending-check]');if(check){const box=check.closest('[data-ending-question]');clearTimeout(endingTimers.get(box));updateEndingFeedback(box);}});
document.addEventListener('ended',e=>{if(e.target.id==='endingPlayer'){const status=document.querySelector('[data-ending-playback]');if(status)status.textContent='Dieser Clip ist zu Ende. Prüfe seine Begründung und sieh dir danach auch die andere Fassung an.';}},true);
document.addEventListener('error',e=>{if(e.target.id==='endingPlayer'){const status=document.querySelector('[data-ending-playback]');if(status)status.textContent='Der Clip konnte nicht geladen werden. Nutze «Clip direkt öffnen» oder prüfe deine Internetverbindung.';}},true);
